document.getElementById('year').textContent=new Date().getFullYear();const glow=document.querySelector('.glow');addEventListener('pointermove',e=>{glow.style.left=e.clientX+'px';glow.style.top=e.clientY+'px'},{passive:true});const c=document.getElementById('space'),x=c.getContext('2d');let dots=[];function size(){const d=devicePixelRatio||1;c.width=innerWidth*d;c.height=innerHeight*d;x.setTransform(d,0,0,d,0,0);dots=Array.from({length:Math.min(90,Math.floor(innerWidth/12))},()=>({x:Math.random()*innerWidth,y:Math.random()*innerHeight,r:Math.random()*1.2+.2,v:Math.random()*.12+.03}))}function draw(){x.clearRect(0,0,innerWidth,innerHeight);x.fillStyle='#93a4c4';dots.forEach(p=>{p.y-=p.v;if(p.y<0)p.y=innerHeight;x.globalAlpha=.15+p.r*.25;x.beginPath();x.arc(p.x,p.y,p.r,0,Math.PI*2);x.fill()});requestAnimationFrame(draw)}addEventListener('resize',size);size();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)draw();
